{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to a user",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "The policy is attached directly to an IAM user, making access harder to govern and increasing the risk that privileges are inadvertently retained. Assigning the policy through a group provides centralized, auditable membership-based access management."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc19-UpdateExistingGlueDevEndpoint-policy-group" {
  name = "${aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name}-policy-group"
}

resource "aws_iam_group_membership" "privesc19-UpdateExistingGlueDevEndpoint-group-membership" {
  name  = "${aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name}-policy-group-membership"
  group = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-policy-group.name
  users = [aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name]
}

resource "aws_iam_group_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy" {
  group      = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-policy-group.name
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}
",
  "fix_summary": "Replaced the direct user policy attachment with a dedicated IAM group policy attachment and added the existing user to that group."
}
